/** DEV-only observational clocks. No runtime/save/RNG/authority access or scheduling. */
const traces=new WeakMap(),LIMIT=120,MARKS=32;
const now=()=>{try{const n=globalThis.performance?.now();return Number.isFinite(n)?n:null}catch{return null}};
export function beginNativeDiagnostic(kind){try{if(import.meta.env?.DEV!==true||!['initial','restore'].includes(kind))return null;const start=now();if(start===null)return null;const token=Object.freeze({});traces.set(token,{kind,start,marks:[],finished:false,frames:new Float64Array(LIMIT),gaps:new Float64Array(LIMIT),count:0,total:0,cursor:0,last:null});return token}catch{return null}}
export function markNativeDiagnostic(token,label){try{const d=traces.get(token),t=now();if(!d||d.finished||t===null||typeof label!=='string'||label.length>64||d.marks.length>=MARKS)return;d.marks.push([label,t-d.start])}catch{}}
export function beginNativeFrame(token,visible){try{const d=traces.get(token);if(!d)return null;if(!visible){d.last=null;return null}const t=now();if(t===null)return null;const sample={t,gap:d.last===null?null:Math.max(0,t-d.last)};d.last=t;return sample}catch{return null}}
export function beginVisibleNativeFrame(token,root){try{if(!traces.has(token))return null;return beginNativeFrame(token,root?.ownerDocument?.visibilityState==='visible')}catch{return null}}
export function endNativeFrame(token,sample){try{const d=traces.get(token),t=now();if(!d||!sample||t===null)return;d.frames[d.cursor]=Math.max(0,t-sample.t);d.gaps[d.cursor]=sample.gap??NaN;d.cursor=(d.cursor+1)%LIMIT;d.count=Math.min(LIMIT,d.count+1);d.total++}catch{}}
export function resetNativeFrameGap(token){try{const d=traces.get(token);if(d)d.last=null}catch{}}
const summary=values=>{const a=values.filter(Number.isFinite).sort((a,b)=>a-b);if(!a.length)return{samples:0};return{samples:a.length,meanMs:a.reduce((x,y)=>x+y,0)/a.length,p50Ms:a[Math.floor((a.length-1)*.5)],p95Ms:a[Math.floor((a.length-1)*.95)],maxMs:a.at(-1)}};
export function nativeFrameReport(token){try{const d=traces.get(token);if(!d)return null;return{retained:d.count,capacity:LIMIT,totalSamples:d.total,nativeFrameElapsed:summary(Array.from(d.frames.subarray(0,d.count))),visibleFrameGap:summary(Array.from(d.gaps.subarray(0,d.count))),scope:'Native host synchronous frame elapsed and visible sampling gaps; not GPU time, whole-app FPS, heap, or device guarantee'}}catch{return null}}
export function finishNativeDiagnostic(token,status){try{const d=traces.get(token),t=now();if(!d||d.finished||t===null)return null;d.finished=true;return{kind:d.kind,status:status==='ok'?'ok':'failed',totalMs:Math.max(0,t-d.start),marks:d.marks.map(([label,elapsedMs])=>({label,elapsedMs})),scope:'App mount-ready performance.now, before first paint; excludes CUA wait-to-observation; no game state included'}}catch{return null}}
export function publishNativeDiagnostic(token,status,root,previousFrames=null){try{const timing=finishNativeDiagnostic(token,status);if(!timing)return;const report={timing,previousVisibleFrames:previousFrames};try{console.info('[DEV native timing]',JSON.stringify(report))}catch{}if(!root?.ownerDocument)return;let node=root.querySelector('[data-native-performance]');if(!node){node=root.ownerDocument.createElement('pre');node.setAttribute('data-native-performance','');node.setAttribute('aria-label','DEV 앱 내 성능 측정');node.style.cssText='font-size:11px;white-space:pre-wrap;max-height:12em;overflow:auto';root.append(node)}node.textContent=JSON.stringify(report,null,2)}catch{}}
